const inputData = $input.first().json;
const tenantId = inputData.tenant_id;

// Validação de UUID
const uuidRegex = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

if (!tenantId || typeof tenantId !== 'string' || !uuidRegex.test(tenantId.trim())) {
  return [{
    json: {
      is_valid: false,
      status: "validation_error",
      code: "INVALID_TENANT_ID",
      message: "O parâmetro 'tenant_id' é obrigatório e deve ser um UUID válido (ex: 'aaaaaaaa-0000-0000-0000-000000000001')",
      timestamp: new Date().toISOString()
    }
  }];
}

return [{
  json: {
    is_valid: true,
    tenant_id: tenantId.trim()
  }
}];

const items = $input.all();
const first = items[0];

if (first.error) {
  return [{
    json: {
      status: "error",
      code: "DB_QUERY_ERROR",
      message: "Erro ao consultar tenant no PostgreSQL",
      error_details: first.error.message || "Erro desconhecido",
      timestamp: new Date().toISOString()
    }
  }];
}

if (items.length === 0 || !first.json || !first.json.tenant_id) {
  return [{
    json: {
      status: "error",
      code: "TENANT_NOT_FOUND",
      message: "Tenant não encontrado no banco de dados sdtech_soluctions",
      timestamp: new Date().toISOString()
    }
  }];
}

const tenant = first.json;
return [{
  json: {
    status: "success",
    code: "TENANT_FOUND",
    message: "Tenant localizado com sucesso",
    data: {
      tenant_id: tenant.tenant_id,
      tenant_code: tenant.tenant_code || null,
      name: tenant.name,
      legal_name: tenant.legal_name || null,
      status: tenant.status,
      timezone: tenant.timezone,
      created_at: tenant.created_at
    },
    timestamp: new Date().toISOString()
  }
}];
